/* css/radio.css */
html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: #070b14; color: #fff;
  font-family: "SamsungOneArabic", "Samsung One Arabic", "TizenSans", "Noto Sans Arabic", "Noto Kufi Arabic", Tahoma, Arial, sans-serif;
  -webkit-font-smoothing: antialiased; }
* { box-sizing: border-box; }
#app { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; -webkit-transform-origin: 0 0; transform-origin: 0 0; }
/* living picture: clouds drift behind the pyramids, the Nile ripples and sparkles,
   the felucca rocks on the water and a few birds cross the sky now and then */
.scene { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; background: #0b1424;
  -webkit-animation: kb 50s ease-in-out infinite alternate; animation: kb 50s ease-in-out infinite alternate; will-change: transform; }
.scene .full { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }
.sun { position: absolute; left: 1500px; top: 160px; width: 760px; height: 760px; border-radius: 50%;
  background: -webkit-radial-gradient(center, circle, rgba(255,238,196,0.75) 0%, rgba(255,230,180,0.25) 35%, rgba(255,230,180,0) 70%);
  background: radial-gradient(circle at center, rgba(255,238,196,0.75) 0%, rgba(255,230,180,0.25) 35%, rgba(255,230,180,0) 70%);
  -webkit-animation: glow 9s ease-in-out infinite alternate; animation: glow 9s ease-in-out infinite alternate; }
.sky-clouds { position: absolute; left: 0; top: 0; width: 3840px; height: 560px; background: url(images/nile-clouds.webp) repeat-x; background-size: 1920px 560px;
  -webkit-animation: drift 90s linear infinite; animation: drift 90s linear infinite; will-change: transform; }
.water, .glints { position: absolute; left: 0; top: 640px; width: 1920px; height: 440px; background-repeat: no-repeat; background-size: 1920px 440px; }
.water { background-image: url(images/nile-water.webp); opacity: 0.6;
  -webkit-animation: ripple 4.5s ease-in-out infinite alternate; animation: ripple 4.5s ease-in-out infinite alternate; will-change: transform; }
.glints { width: 1980px; left: -30px; }
.glints.g1 { background-image: url(images/nile-glints1.webp); -webkit-animation: twinkle 3.2s ease-in-out infinite, gdrift 16s ease-in-out infinite alternate; animation: twinkle 3.2s ease-in-out infinite, gdrift 16s ease-in-out infinite alternate; }
.glints.g2 { background-image: url(images/nile-glints2.webp); -webkit-animation: twinkle 3.2s ease-in-out -1.6s infinite, gdrift 21s ease-in-out infinite alternate-reverse; animation: twinkle 3.2s ease-in-out -1.6s infinite, gdrift 21s ease-in-out infinite alternate-reverse; }
.boat { position: absolute; left: 1530px; top: 525px; width: 115px; height: 187px; -webkit-transform-origin: 55% 92%; transform-origin: 55% 92%;
  -webkit-animation: bob 5s ease-in-out infinite alternate; animation: bob 5s ease-in-out infinite alternate; will-change: transform; }
.birds { position: absolute; left: 0; top: 300px; width: 180px; height: 70px; -webkit-animation: fly 60s linear infinite; animation: fly 60s linear infinite; }
.birds path { fill: none; stroke: #2b2722; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round;
  -webkit-transform-box: fill-box; transform-box: fill-box; -webkit-transform-origin: 50% 100%; transform-origin: 50% 100%;
  -webkit-animation: flap .55s ease-in-out infinite alternate; animation: flap .55s ease-in-out infinite alternate; }
.birds path:nth-child(2) { -webkit-animation-delay: -.2s; animation-delay: -.2s; }
.birds path:nth-child(3) { -webkit-animation-delay: -.35s; animation-delay: -.35s; }
.birds path:nth-child(4) { -webkit-animation-delay: -.1s; animation-delay: -.1s; }
@-webkit-keyframes kb { from { -webkit-transform: scale(1); } to { -webkit-transform: scale(1.06) translate3d(-18px,-6px,0); } }
@keyframes kb { from { transform: scale(1); } to { transform: scale(1.06) translate3d(-18px,-6px,0); } }
@-webkit-keyframes glow { from { opacity: 0.55; } to { opacity: 1; } }
@keyframes glow { from { opacity: 0.55; } to { opacity: 1; } }
@-webkit-keyframes drift { from { -webkit-transform: translate3d(0,0,0); } to { -webkit-transform: translate3d(-1920px,0,0); } }
@keyframes drift { from { transform: translate3d(0,0,0); } to { transform: translate3d(-1920px,0,0); } }
@-webkit-keyframes ripple { from { -webkit-transform: translate3d(0,0,0); } to { -webkit-transform: translate3d(7px,2px,0); } }
@keyframes ripple { from { transform: translate3d(0,0,0); } to { transform: translate3d(7px,2px,0); } }
@-webkit-keyframes twinkle { 0%, 100% { opacity: 0.15; } 50% { opacity: 0.95; } }
@keyframes twinkle { 0%, 100% { opacity: 0.15; } 50% { opacity: 0.95; } }
@-webkit-keyframes gdrift { from { -webkit-transform: translate3d(0,0,0); } to { -webkit-transform: translate3d(30px,0,0); } }
@keyframes gdrift { from { transform: translate3d(0,0,0); } to { transform: translate3d(30px,0,0); } }
@-webkit-keyframes bob { from { -webkit-transform: rotate(-1.3deg) translate3d(0,0,0); } to { -webkit-transform: rotate(1.5deg) translate3d(0,2px,0); } }
@keyframes bob { from { transform: rotate(-1.3deg) translate3d(0,0,0); } to { transform: rotate(1.5deg) translate3d(0,2px,0); } }
/* birds fly from right to left in 36 s, then the sky stays empty for the rest of the minute */
@-webkit-keyframes fly { 0% { -webkit-transform: translate3d(2050px,0,0); } 30% { -webkit-transform: translate3d(1250px,-30px,0); } 60% { -webkit-transform: translate3d(-260px,10px,0); } 100% { -webkit-transform: translate3d(-260px,10px,0); } }
@keyframes fly { 0% { transform: translate3d(2050px,0,0); } 30% { transform: translate3d(1250px,-30px,0); } 60% { transform: translate3d(-260px,10px,0); } 100% { transform: translate3d(-260px,10px,0); } }
@-webkit-keyframes flap { from { -webkit-transform: scaleY(1); } to { -webkit-transform: scaleY(0.3); } }
@keyframes flap { from { transform: scaleY(1); } to { transform: scaleY(0.3); } }
#stagebg { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; -webkit-transform-origin: 0 0; transform-origin: 0 0; }
.shade { position: absolute; left: 0; top: 0; right: 0; bottom: 0;
  background: -webkit-linear-gradient(top, rgba(4,8,18,0.6) 0%, rgba(4,8,18,0.1) 24%, rgba(4,8,18,0) 45%, rgba(4,8,18,0.55) 70%, rgba(4,8,18,0.92) 100%);
  background: linear-gradient(to bottom, rgba(4,8,18,0.6) 0%, rgba(4,8,18,0.1) 24%, rgba(4,8,18,0) 45%, rgba(4,8,18,0.55) 70%, rgba(4,8,18,0.92) 100%); }
.shadow { text-shadow: 0 3px 16px rgba(0,0,0,0.6), 0 1px 3px rgba(0,0,0,0.5); }

/* clock + dates (top right) */
.hero { position: absolute; right: 80px; top: 60px; }
.time { display: -webkit-flex; display: flex; -webkit-align-items: flex-end; align-items: flex-end; }
.clock { font-size: 124px; font-weight: 800; line-height: 0.95; letter-spacing: -2px; }
.ampm { font-size: 34px; font-weight: 700; color: #ffd27a; margin: 0 16px 12px 0; }
.date { font-size: 32px; font-weight: 700; margin-top: 12px; }
.hijri { font-size: 28px; font-weight: 700; margin-top: 6px; color: #ffd27a; }

/* station title (top left) */
.brand { position: absolute; left: 80px; top: 70px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; }
.brand .logo { width: 96px; height: 96px; border-radius: 28px; margin-left: 24px;
  background: -webkit-linear-gradient(315deg, #f5c25b, #c98a1b); background: linear-gradient(135deg, #f5c25b, #c98a1b);
  display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; box-shadow: 0 16px 40px rgba(0,0,0,0.4); }
.brand .logo svg { width: 58px; height: 58px; fill: #1b1200; }
.brand h1 { margin: 0; font-size: 46px; font-weight: 800; }
.brand p { margin: 6px 0 0; font-size: 26px; color: #e3e8f1; }
.brand p.by { margin-top: 8px; font-size: 21px; font-weight: 600; letter-spacing: 0.4px; color: #ffd27a; text-align: right; opacity: 0.92; }

/* player card (bottom center) */
.player { position: absolute; left: 50%; bottom: 182px; width: 740px; margin-left: -370px; height: 156px; padding: 0 34px;
  border-radius: 34px; background: rgba(8,12,22,0.62); border: 2px solid rgba(255,255,255,0.14);
  display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; box-shadow: 0 24px 60px rgba(0,0,0,0.4); }
.btn { width: 104px; height: 104px; border-radius: 50%; -webkit-flex-shrink: 0; flex-shrink: 0;
  background: #ffb020; color: #1b1200; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center;
  box-shadow: 0 12px 34px rgba(255,160,0,0.45); }
.btn svg { width: 56px; height: 56px; fill: currentColor; }
.info { -webkit-flex: 1; flex: 1; margin-right: 30px; }
.status { font-size: 21px; color: #d6dde9; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; }
.live { display: inline-block; padding: 3px 13px; border-radius: 9px; background: #e5484d; color: #fff; font-size: 18px; font-weight: 800; margin-left: 16px; }
.live.off { background: rgba(255,255,255,0.18); }
.title { font-size: 33px; font-weight: 800; margin-top: 6px; }
.eq { display: -webkit-flex; display: flex; -webkit-align-items: flex-end; align-items: flex-end; height: 58px; margin-right: 16px; }
.eq i { display: block; width: 10px; margin-left: 7px; border-radius: 5px; background: #ffb020; height: 14px; }
.playing .eq i { -webkit-animation: eq 1s ease-in-out infinite; animation: eq 1s ease-in-out infinite; }
.playing .eq i:nth-child(2) { -webkit-animation-delay: .2s; animation-delay: .2s; }
.playing .eq i:nth-child(3) { -webkit-animation-delay: .4s; animation-delay: .4s; }
.playing .eq i:nth-child(4) { -webkit-animation-delay: .1s; animation-delay: .1s; }
.playing .eq i:nth-child(5) { -webkit-animation-delay: .3s; animation-delay: .3s; }
@-webkit-keyframes eq { 0%, 100% { height: 14px; } 50% { height: 64px; } }
@keyframes eq { 0%, 100% { height: 14px; } 50% { height: 64px; } }

/* prayer strip (bottom) */
.prayer { position: absolute; left: 80px; right: 80px; bottom: 44px; height: 100px; display: -webkit-flex; display: flex;
  -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; }
.pr-nx { height: 80px; padding: 8px 22px; border-radius: 18px; margin-left: 12px;
  background: -webkit-linear-gradient(315deg, #ffb020, #ff7a3d); background: linear-gradient(135deg, #ffb020, #ff7a3d); color: #1b1200; text-align: center; }
.pr-nx small { display: block; font-size: 17px; font-weight: 800; opacity: 0.8; }
.pr-nx b { display: block; font-size: 32px; font-weight: 800; letter-spacing: 1px; }
.pr-it { height: 80px; width: 142px; margin-left: 12px; padding: 8px 0; border-radius: 18px; text-align: center;
  background: rgba(8,12,22,0.58); border: 2px solid rgba(255,255,255,0.12); }
.pr-it small { display: block; font-size: 18px; color: #c3cbdb; }
.pr-it b { display: block; font-size: 27px; font-weight: 800; margin-top: 2px; }
.pr-it.next { border-color: #ffb020; background: rgba(255,176,32,0.18); }
.pr-it.next small, .pr-it.next b { color: #ffd27a; }
.pr-it.past { opacity: 0.55; }
.city { position: absolute; left: 0; right: 0; bottom: 146px; text-align: center; font-size: 19px; font-weight: 700; }
.hint { position: absolute; left: 80px; right: 80px; bottom: 14px; text-align: center; font-size: 20px; color: rgba(255,255,255,0.55); }

/* ===== one line at the bottom: radio | prayer times | countdown ===== */
.dock { position: absolute; left: 70px; right: 70px; bottom: 48px; height: 136px; border-radius: 30px;
  background: rgba(8,12,22,0.62); border: 2px solid rgba(255,255,255,0.14); box-shadow: 0 24px 60px rgba(0,0,0,0.4);
  display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; padding: 0 30px; }
.dock .player { position: static; left: auto; bottom: auto; margin: 0; width: 520px; height: auto; padding: 0; border: 0; border-radius: 0; background: none; box-shadow: none;
  -webkit-flex-shrink: 0; flex-shrink: 0; }
.dock .btn { width: 92px; height: 92px; box-shadow: 0 10px 26px rgba(255,160,0,0.4); }
.dock .btn svg { width: 50px; height: 50px; }
.dock .info { margin-right: 22px; }
.dock .status { font-size: 17px; }
.dock .live { font-size: 16px; padding: 2px 11px; border-radius: 8px; margin-left: 10px; }
.dock .title { font-size: 30px; margin-top: 4px; white-space: nowrap; }
.dock .sub { font-size: 17px; color: #c9d1de; margin-top: 2px; }
.dock .eq { height: 46px; margin-right: 6px; }
.dock .eq i { width: 8px; margin-left: 6px; }
.dock .sep { width: 2px; height: 92px; background: rgba(255,255,255,0.14); margin: 0 26px; -webkit-flex-shrink: 0; flex-shrink: 0; }
.dock .times { -webkit-flex: 1; flex: 1; position: relative; height: 104px; }
.dock .city { position: absolute; left: auto; right: 0; top: 0; bottom: auto; text-align: right; font-size: 16px; color: #c3cbdb; text-shadow: none; }
.dock .prayer { position: absolute; left: 0; right: 0; top: 24px; bottom: auto; height: 80px; -webkit-justify-content: space-between; justify-content: space-between; }
.dock .pr-it { width: auto; -webkit-flex: 1; flex: 1; height: 76px; margin: 0; padding: 8px 0 0; border: 0; border-radius: 0; background: none; position: relative; }
.dock .pr-it + .pr-it { border-right: 1px solid rgba(255,255,255,0.12); }
.dock .pr-it small { font-size: 17px; white-space: nowrap; }
.dock .pr-it b { font-size: 26px; white-space: nowrap; }
.dock .pr-it.next { background: none; }
.dock .pr-it.next:after { content: ""; position: absolute; left: 28%; right: 28%; bottom: 0; height: 4px; border-radius: 2px; background: #ffb020; }
.dock .pr-nx { -webkit-order: 9; order: 9; height: 76px; margin: 0 14px 0 0; padding: 8px 20px; border-radius: 16px; }
.dock .pr-nx small { font-size: 16px; }
.dock .pr-nx b { font-size: 30px; }
.hint { bottom: 12px; font-size: 18px; }


/* choice of station: Egypt (main) / Saudi Arabia */
.stations { display: -webkit-flex; display: flex; margin-top: 6px; }
.st { font-size: 18px; font-weight: 700; padding: 3px 16px; border-radius: 11px; margin-left: 10px; color: #d6dde9;
  background: rgba(255,255,255,0.12); border: 2px solid transparent; cursor: pointer; }
.st.cur { background: #ffb020; color: #1b1200; }
/* message at the bottom, version in the corner */
#toast { position: absolute; left: 50%; bottom: 210px; -webkit-transform: translateX(-50%); transform: translateX(-50%);
  padding: 14px 30px; border-radius: 16px; background: rgba(8,12,22,0.88); color: #fff; font-size: 26px; font-weight: 700;
  white-space: nowrap; opacity: 0; -webkit-transition: opacity .3s; transition: opacity .3s; pointer-events: none; }
#toast.show { opacity: 1; }
.ver { position: absolute; left: 30px; bottom: 14px; font-size: 16px; color: rgba(255,255,255,0.45); cursor: pointer; }

/* dim.css */
/* ===== night light (dim.js) ===== */
#dimmer { position: fixed; left: 0; top: 0; right: 0; bottom: 0; z-index: 900; background: #000; opacity: 0; pointer-events: none;
  -webkit-transition: opacity 1.2s ease; transition: opacity 1.2s ease; }
#dimmer.on { opacity: 0.9; pointer-events: auto; }
#dim-hint { position: fixed; left: 0; right: 0; bottom: 40px; z-index: 901; text-align: center; font-size: 26px; color: rgba(255,255,255,0.5); opacity: 0;
  -webkit-transition: opacity 0.8s ease; transition: opacity 0.8s ease; pointer-events: none; }
#dim-hint.show { opacity: 1; }
/* nothing moves while it is dark (less flicker, less work for the TV) */
body.dimmed .scene, body.dimmed .scene *, body.dimmed .birds, body.dimmed .birds * { -webkit-animation-play-state: paused !important; animation-play-state: paused !important; }

