/* ==========================================================================
   saudi-time.js — clock, Gregorian and Hijri (Umm Al-Qura) dates in
   Saudi time (UTC+3, no daylight saving), whatever the TV's own timezone.
   Use the getUTC* methods on the Date returned by now().
   ========================================================================== */
var SaudiTime = (function () {
  var DAYS = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
  var MONTHS = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
  var HMONTHS = ['محرم', 'صفر', 'ربيع الأول', 'ربيع الآخر', 'جمادى الأولى', 'جمادى الآخرة',
    'رجب', 'شعبان', 'رمضان', 'شوال', 'ذو القعدة', 'ذو الحجة'];

  function now() { return new Date(new Date().getTime() + 3 * 3600000); }

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  /* 12-hour clock text with ص / م */
  function clock12(h, m) {
    var ampm = h < 12 ? 'ص' : 'م';
    var hh = h % 12; if (hh === 0) hh = 12;
    return hh + ':' + pad(m) + ' ' + ampm;
  }

  function parts12(d) {
    var h = d.getUTCHours(), hh = h % 12; if (hh === 0) hh = 12;
    if (api.use24) return { time: pad(h) + ':' + pad(d.getUTCMinutes()), ampm: '' };
    return { time: hh + ':' + pad(d.getUTCMinutes()), ampm: h < 12 ? 'صباحاً' : 'مساءً' };
  }

  /* short clock text that follows the 12/24-hour setting */
  function fmt(h, m) { return api.use24 ? pad(h) + ':' + pad(m) : clock12(h, m); }

  function gregorian(d) {
    return DAYS[d.getUTCDay()] + '، ' + d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear();
  }

  /* ---- Hijri: Umm Al-Qura through Intl when the TV supports it ---- */
  var intlFmt = null, intlTried = false;
  function intlHijri(d) {
    if (!intlTried) {
      intlTried = true;
      try {
        var f = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura-nu-latn', { timeZone: 'UTC', day: 'numeric', month: 'numeric', year: 'numeric' });
        if (f.resolvedOptions().calendar === 'islamic-umalqura') intlFmt = f;
      } catch (e) { intlFmt = null; }
    }
    if (!intlFmt) return null;
    try {
      var out = {}, ps = intlFmt.formatToParts(d);
      for (var i = 0; i < ps.length; i++) {
        if (ps[i].type === 'day') out.day = parseInt(ps[i].value, 10);
        if (ps[i].type === 'month') out.month = parseInt(ps[i].value, 10);
        if (ps[i].type === 'year') out.year = parseInt(ps[i].value, 10);
      }
      if (out.day && out.month && out.year) return out;
    } catch (e) {}
    return null;
  }

  /* fallback: tabular Islamic calendar (may differ by a day from Umm Al-Qura) */
  function tabularHijri(d) {
    var jd = Math.floor(d.getTime() / 86400000) + 2440588;     /* civil day number */
    var l = jd - 1948440 + 10632;
    var n = Math.floor((l - 1) / 10631);
    l = l - 10631 * n + 354;
    var j = Math.floor((10985 - l) / 5316) * Math.floor((50 * l) / 17719) + Math.floor(l / 5670) * Math.floor((43 * l) / 15238);
    l = l - Math.floor((30 - j) / 15) * Math.floor((17719 * j) / 50) - Math.floor(j / 16) * Math.floor((15238 * j) / 43) + 29;
    var month = Math.floor((24 * l) / 709);
    var day = l - Math.floor((709 * month) / 24);
    var year = 30 * n + j - 30;
    return { day: day, month: month, year: year };
  }

  /* d is a "Saudi" Date from now(): its UTC fields are Saudi local fields */
  function hijri(d) {
    var noon = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 12));
    return intlHijri(noon) || tabularHijri(noon);
  }

  function hijriText(d) {
    var h = hijri(d);
    return h.day + ' ' + HMONTHS[h.month - 1] + ' ' + h.year + 'هـ';
  }

  var api = { now: now, clock12: clock12, parts12: parts12, fmt: fmt, gregorian: gregorian, hijri: hijri,
    hijriText: hijriText, pad: pad, use24: false, HMONTHS: HMONTHS };
  return api;
})();

/* ==========================================================================
   prayer.js — prayer times calculated on the TV (no internet needed)
   Method: Umm Al-Qura (Saudi Arabia): Fajr 18.5°, Isha = Maghrib + 90 min
   (120 min in Ramadan), Asr standard (shadow = 1). Saudi time = UTC+3.
   Astronomical part follows the well-known PrayTimes.org algorithm.
   ========================================================================== */
var Prayer = (function () {

  var CITIES = [
    { id: 'riyadh', name: 'الرياض', lat: 24.7136, lng: 46.6753 },
    { id: 'makkah', name: 'مكة المكرمة', lat: 21.4225, lng: 39.8262 },
    { id: 'madinah', name: 'المدينة المنورة', lat: 24.4672, lng: 39.6111 },
    { id: 'jeddah', name: 'جدة', lat: 21.4858, lng: 39.1925 },
    { id: 'dammam', name: 'الدمام', lat: 26.4207, lng: 50.0888 },
    { id: 'khobar', name: 'الخبر', lat: 26.2172, lng: 50.1971 },
    { id: 'hofuf', name: 'الأحساء', lat: 25.3833, lng: 49.5856 },
    { id: 'taif', name: 'الطائف', lat: 21.2703, lng: 40.4158 },
    { id: 'buraydah', name: 'بريدة', lat: 26.3592, lng: 43.9818 },
    { id: 'hail', name: 'حائل', lat: 27.5114, lng: 41.7208 },
    { id: 'tabuk', name: 'تبوك', lat: 28.3835, lng: 36.5662 },
    { id: 'abha', name: 'أبها', lat: 18.2465, lng: 42.5117 },
