    var h = '<div class="pr-nx"><small>' + esc(nx.name) + ' بعد</small><b id="count" dir="ltr"></b></div>';
    for (var i = 0; i < list.length; i++) {
      var it = list[i];
      var isNext = nx.tomorrow ? it.key === 'fajr' : it.key === nx.key;
      var cls = 'pr-it' + (isNext ? ' next' : '') + (!nx.tomorrow && !isNext && it.minutes <= lastMin ? ' past' : '');
      h += '<div class="' + cls + '"><small>' + esc(it.name) + '</small><b>' + esc(it.text) + '</b></div>';
    }
    $('prayer').innerHTML = h;
  }

  function updateCountdown() {
    var el = $('count');
    if (!el || !nextPrayer) return;
    var d = SaudiTime.now();
    var nowSec = d.getUTCHours() * 3600 + d.getUTCMinutes() * 60 + d.getUTCSeconds();
    var nx = nextPrayer, mins = 0, l = nx.today.list;
    if (nx.tomorrow) mins = l[0].minutes + 1440;
    else for (var i = 0; i < l.length; i++) if (l[i].key === nx.key) mins = l[i].minutes;
    var left = Math.max(0, mins * 60 - nowSec);
    el.innerHTML = Math.floor(left / 3600) + ':' + pad(Math.floor((left % 3600) / 60)) + ':' + pad(left % 60);
    if (left === 0) lastMin = -1;
  }

  /* ---------------- choice of station ---------------- */
  function renderStation() {
    var h = '';
    for (var i = 0; i < STATIONS.length; i++) {
      h += '<span class="st' + (STATIONS[i] === station ? ' cur' : '') + '" data-st="' + i + '">' + STATIONS[i].chip + '</span>';
    }
    $('stations').innerHTML = h;
    var f = document.querySelectorAll('.from');
    for (var j = 0; j < f.length; j++) f[j].innerHTML = station.from;
  }
  function setStation(i) {
    i = (i + STATIONS.length) % STATIONS.length;
    if (STATIONS[i] === station) return;
    station = STATIONS[i];
    STREAMS = station.streams;
    streamIdx = 0;
    try { localStorage.setItem('radio.station', station.id); } catch (e) {}
    renderStation();
    toast('إذاعة القرآن الكريم ' + station.from);
    if (wantPlay) start();
  }

  /* ---------------- small message at the bottom (the updater uses it too) ---------------- */
  var toastTimer = null;
  function toast(msg, ms) {
    var t = $('toast');
    if (!t) return;
    t.innerHTML = esc(msg);
    t.className = 'show';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { t.className = ''; }, ms || 3500);
  }
  window.UI = window.UI || { toast: toast };

  /* ---------------- updates (from the internet, see js/ota.js) ---------------- */
  function checkUpdate() {
    if (!window.OTA) return;
    toast('بيدوّر على تحديث...');
    OTA.check(function (r) {
      if (r.status === 'ready') {
        toast('تحديث ' + r.version + ' — جاري التشغيل...');
        setTimeout(function () { location.reload(); }, 1500);
      }
      else if (r.status === 'latest') toast('عندك آخر إصدار (' + OTA.running() + ')');
      else if (r.status === 'needShell') toast('تحديث كبير متاح — محتاج يتسطّب من اللابتوب');
      else if (r.status === 'busy') toast('بيدوّر على تحديث بالفعل...');
      else toast('مش قادر يوصل لسيرفر التحديثات — اتأكد من الإنترنت');
    });
  }

  /* ---------------- keys ---------------- */
  /* leaving the app: go back to the home screen app ("الواجهة") when this TV has it */
  function backHome(then) {
    var done = false;
    function fin() { if (done) return; done = true; then(); }
    try { tizen.application.launch('MAHomeTV01.TVHome', fin, fin); } catch (e) { fin(); }
    setTimeout(fin, 1500);
  }
  function onKey(e) {
    var c = e.keyCode;
    if (c === 37 || c === 39) { e.preventDefault(); setStation(STATIONS.indexOf(station) + (c === 37 ? 1 : -1)); return; }
    if (c === 38) { e.preventDefault(); checkUpdate(); return; }
    if (c === 13 || c === 10252 || c === 32) {
      e.preventDefault();
      if (now() - revivedAt < 500) return;      /* this press already brought the sound back: do not stop it */
      if (wantPlay) stop(); else start();
    }
    else if (c === 415) { if (!wantPlay) start(); }
    else if (c === 19 || c === 413) { if (wantPlay) stop(); }
    else if (c === 10009 || c === 27 || c === 8) {
      e.preventDefault();
      stop();   /* also turns the screen saver back on */
      backHome(function () { try { tizen.application.getCurrentApplication().exit(); } catch (err) {} });
    }
  }

  /* the 1920x1080 design grows to the screen's shape: on a wide car screen the
     page gets wider (the picture is enlarged to cover it) so nothing is left empty */
  function fit() {
    var w = window.innerWidth, h = window.innerHeight;
    if (!w || !h) return;
    var W = 1920, H = 1080, r = w / h;
    if (r > W / H + 0.01) W = Math.round(H * r);
    else if (r < W / H - 0.01) H = Math.round(W / r);
    var app = $('app');
    app.style.width = W + 'px'; app.style.height = H + 'px';
    var s = Math.min(w / W, h / H);
    var t = 'translate(' + Math.round((w - W * s) / 2) + 'px,' + Math.round((h - H * s) / 2) + 'px) scale(' + s + ')';
    app.style.transform = t; app.style.webkitTransform = t;
    var c = Math.max(W / 1920, H / 1080), bg = $('stagebg');
    var tb = c > 1.001 ? 'translate(' + Math.round((W - 1920 * c) / 2) + 'px,' + Math.round((H - 1080 * c) / 2) + 'px) scale(' + c + ')' : '';
    bg.style.transform = tb; bg.style.webkitTransform = tb;
  }


  window.onload = function () {
    if (window.OTA) OTA.start();   /* this version started: keep it, look for updates later */
    renderStation();
    $('stations').addEventListener('click', function (e) {
      var i = e.target && e.target.getAttribute ? e.target.getAttribute('data-st') : null;
      if (i !== null) { e.stopPropagation(); setStation(parseInt(i, 10)); }
    });
    $('ver').innerHTML = 'الإصدار ' + (window.OTA ? OTA.running() : '');
    $('ver').addEventListener('click', checkUpdate);
    fit();
    window.addEventListener('resize', fit);
    try { tizen.tvinputdevice.registerKeyBatch(['MediaPlayPause', 'MediaPlay', 'MediaPause', 'MediaStop']); } catch (e) {}
    audio = $('audio');
    if (window.webapis && webapis.avplay) av = webapis.avplay;
    audio.addEventListener('playing', function () { progressed(); setState('playing'); });
    audio.addEventListener('timeupdate', progressed);
    audio.addEventListener('waiting', function () { if (wantPlay) setState('loading'); });
    audio.addEventListener('error', retry);
    audio.addEventListener('ended', retry);
    audio.addEventListener('stalled', function () { if (wantPlay) { clearTimeout(retryTimer); retryTimer = setTimeout(function () { if (wantPlay && audio.paused) retry(); }, 8000); } });
    document.addEventListener('keydown', onKey);
    document.addEventListener('keydown', revive, true);   /* runs even when the night light eats the key */
    document.addEventListener('visibilitychange', function () {
      if (document.hidden) { if (wantPlay) { stop(); wantPlay = true; } }
      else if (wantPlay) setTimeout(function () { if (wantPlay) start(); }, 300);
    });
    tick();
    setInterval(tick, 1000);
    setInterval(watch, 10000);
    start();
  };
  /* the updater's loader checks this to know the code started */
  window.RadioApp = { station: function () { return station.id; } };
})();

/* ==========================================================================
   dim.js — night light. The picture goes dark while the radio keeps playing,
   so the TV light does not disturb anyone who wants to sleep on the radio.
   - ▼ (down) or the blue button: dim now
   - any button (or a tap): back to normal; that press does nothing else
   - late at night (22:00 – 05:00 Riyadh time) it dims by itself after
     15 minutes without any button pressed
   ========================================================================== */
(function () {
  var IDLE_MS = 15 * 60000;
  var on = false, last = new Date().getTime(), hintTimer = null;

  function $(id) { return document.getElementById(id); }

  function riyadhHour() {
    var d = window.SaudiTime ? SaudiTime.now() : new Date(new Date().getTime() + 3 * 3600000);
    return d.getUTCHours();
  }
  function isNight() { var h = riyadhHour(); return h >= 22 || h < 5; }

  function set(v) {
    on = v;
    if (!v && window.RadioRevive) window.RadioRevive();   /* waking up: make sure the sound is on */
    var d = $('dimmer');
    if (!d) return;
    d.className = v ? 'on' : '';
    if (v) document.body.className += ' dimmed';
    else document.body.className = document.body.className.replace(/\s*dimmed/g, '');
    clearTimeout(hintTimer);
    var h = $('dim-hint');
    if (h) {
      h.className = v ? 'show' : '';
      if (v) hintTimer = setTimeout(function () { h.className = ''; }, 5000);
    }
  }

  window.Dimmer = { on: function () { set(true); }, off: function () { set(false); }, active: function () { return on; } };

  function swallow(e) {
    e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    e.stopPropagation();
  }

  /* runs before the radio's own key handler */
  document.addEventListener('keydown', function (e) {
    last = new Date().getTime();
    var c = e.keyCode;
    if (on) { set(false); swallow(e); return; }
    if (c === 40 || c === 406) { set(true); swallow(e); }
  }, true);

  /* touch screens: a tap wakes it */
  function wakeOnTap(e) { last = new Date().getTime(); if (on) { set(false); swallow(e); } }
  document.addEventListener('click', wakeOnTap, true);
  document.addEventListener('touchstart', function (e) { if (on) { last = new Date().getTime(); set(false); swallow(e); } }, true);

  setInterval(function () {
    if (!on && isNight() && new Date().getTime() - last > IDLE_MS) set(true);
  }, 30000);

  function init() {
    try { tizen.tvinputdevice.registerKey('ColorF3Blue'); } catch (e) {}
    if ($('dimmer')) return;
    var d = document.createElement('div');
    d.id = 'dimmer';
    var h = document.createElement('div');
    h.id = 'dim-hint';
    h.innerHTML = 'إضاءة خافتة · اضغط أي زر للرجوع';
    document.body.appendChild(d);
    document.body.appendChild(h);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
